  def test_uploadERGAManifest(self):
    self.driver.get("http://127.0.0.1:8000/copo/")
    self.driver.set_window_size(1188, 840)
    self.driver.find_element(By.XPATH, "//div[div=\"test ERGA profile\"][1]/span[1]/div[1]").click()
