    self.driver.find_element(By.XPATH, "//button[contains(.,\'Ok\')]").click()
    self.driver.find_element(By.ID, "file").send_keys("/Users/zef22hak/development/COPO/selenium_test/data/copo-erga-f01.xlsx")
